class Solution {
    long long gcd(long long a, long long b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    long long lcm(long long a, long long b) {
        if (a == 0 || b == 0) return 0;
        return (a / gcd(a, b)) * b;
    }
public:
    int maxLength(vector<int>& nums) {
        int n = nums.size();
        int maxLen = 0;
        for (int i = 0; i < n; ++i) {
            long long prod = 1;
            long long currGcd = 0;
            long long currLcm = 1;
            for (int j = i; j < n; ++j) {
                long long val = nums[j];
                // Check potential overflow
                if (prod > 2e18 / val) break;
                prod *= val;
                currGcd = currGcd == 0 ? val : gcd(currGcd, val);
                currLcm = lcm(currLcm, val);
                if (prod == currGcd * currLcm) {
                    maxLen = max(maxLen, j - i + 1);
                }
            }
        }
        return maxLen;
    }
};

class Solution {
    private long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    private long lcm(long a, long b) {
        if (a == 0 || b == 0) return 0;
        return (a / gcd(a, b)) * b;
    }
    public int maxLength(int[] nums) {
        int n = nums.length;
        int maxLen = 0;
        for (int i = 0; i < n; ++i) {
            long prod = 1;
            long currGcd = 0;
            long currLcm = 1;
            for (int j = i; j < n; ++j) {
                long val = nums[j];
                if (prod > Long.MAX_VALUE / val) break;
                prod *= val;
                currGcd = currGcd == 0 ? val : gcd(currGcd, val);
                currLcm = lcm(currLcm, val);
                if (prod == currGcd * currLcm) {
                    maxLen = Math.max(maxLen, j - i + 1);
                }
            }
        }
        return maxLen;
    }
}

